package com.bank.recursion;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class RecursionDemo {

    private static final Logger log = Logger.getLogger(RecursionDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Build Rajesh's sweep chain: 100000 -> 50000 -> 25000 -> null
        SweepAccount third = new SweepAccount("SWP-3", new BigDecimal("25000"), null);
        SweepAccount second = new SweepAccount("SWP-2", new BigDecimal("50000"), third);
        SweepAccount first = new SweepAccount("SWP-1", new BigDecimal("100000"), second);

        SweepCalculator calculator = new SweepCalculator();
        BigDecimal total = calculator.totalBalance(first);

        log.info(() -> "Combined sweep balance for Rajesh: Rs." + total);
    }
}

// ─── Would be in model/SweepAccount.java in a real project ───
class SweepAccount {
    private final String id;
    private final BigDecimal balance;
    private final SweepAccount next; // link to the next account, or null at the end

    SweepAccount(String id, BigDecimal balance, SweepAccount next) {
        this.id = id;
        this.balance = balance;
        this.next = next;
    }

    String getId() { return id; }
    BigDecimal getBalance() { return balance; }
    SweepAccount getNext() { return next; }
}

// ─── Would be in service/SweepCalculator.java in a real project ───
class SweepCalculator {

    private static final Logger log = Logger.getLogger(SweepCalculator.class.getName());

    // Recursive total: this balance + total of the rest of the chain.
    BigDecimal totalBalance(SweepAccount account) {
        // BASE CASE: empty chain contributes nothing. This stops the recursion.
        if (account == null) {
            log.fine("Base case reached — returning zero.");
            return BigDecimal.ZERO;
        }
        // RECURSIVE CASE: shrink the problem by moving to the next account.
        log.info(() -> "Visiting " + account.getId() + " balance Rs." + account.getBalance());
        BigDecimal restOfChain = totalBalance(account.getNext());
        return account.getBalance().add(restOfChain);
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("[%1$tF %1$tT] %2$-7s %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                formatMessage(record));
    }
}
